import{_ as a,o as t,c as s,a2 as e}from"./chunks/framework.O93z6AWZ.js";const g=JSON.parse('{"title":"Hướng dẫn Literature Review bằng AI","description":"","frontmatter":{"title":"Hướng dẫn Literature Review bằng AI"},"headers":[],"relativePath":"huong_dan_literature_review.md","filePath":"huong_dan_literature_review.md"}'),i={name:"huong_dan_literature_review.md"};function p(h,n,c,o,l,r){return t(),s("div",null,[...n[0]||(n[0]=[e(`<h1 id="quy-trinh-5-buoc-literature-review-bang-ai" tabindex="-1">Quy trình 5 Bước Literature Review bằng AI <a class="header-anchor" href="#quy-trinh-5-buoc-literature-review-bang-ai" aria-label="Permalink to &quot;Quy trình 5 Bước Literature Review bằng AI&quot;">​</a></h1><p>Một quy trình nghiên cứu hoàn chỉnh (End-to-End Research Lifecycle) từ khi có một chủ đề (topic) cho đến khi xuất bản công trình khoa học bao gồm <strong>5 giai đoạn chiến lược</strong>. Trong đó, quy trình <strong>Literature Review 5 bước bằng AI</strong> đóng vai trò móng cọc ở Giai đoạn 1. Tài liệu này cung cấp hướng dẫn chi tiết và các bộ Prompts mẫu để sinh viên dễ dàng áp dụng.</p><hr><h2 id="tong-quan-5-giai-đoan-nghien-cuu-toan-dien-end-to-end-research" tabindex="-1">TỔNG QUAN: 5 GIAI ĐOẠN NGHIÊN CỨU TOÀN DIỆN (END-TO-END RESEARCH) <a class="header-anchor" href="#tong-quan-5-giai-đoan-nghien-cuu-toan-dien-end-to-end-research" aria-label="Permalink to &quot;TỔNG QUAN: 5 GIAI ĐOẠN NGHIÊN CỨU TOÀN DIỆN (END-TO-END RESEARCH)&quot;">​</a></h2><ol><li><strong>Giai đoạn 1: Literature Review &amp; Khám phá Research Gap (Xác định base)</strong><ul><li>Quét bản đồ tri thức, thu thập bài báo cốt lõi, kiểm chứng học thuật, đọc sâu và cấu trúc cơ sở dữ liệu.</li></ul></li><li><strong>Giai đoạn 2: Định hình Câu hỏi nghiên cứu &amp; Đề xuất (Research Proposal)</strong><ul><li>Chuyển hóa Gap thành Câu hỏi nghiên cứu (RQs). Đề xuất tính mới (Novelty) và Giả thuyết.</li></ul></li><li><strong>Giai đoạn 3: Thiết kế Phương pháp &amp; Chuẩn bị (Methodology &amp; Setup)</strong><ul><li>Chuẩn bị dữ liệu (Dataset Pipeline), xây dựng kiến trúc mô hình, chọn Baseline và Metrics.</li></ul></li><li><strong>Giai đoạn 4: Thực nghiệm &amp; Đánh giá (Experimentation &amp; Validation)</strong><ul><li>Lập trình huấn luyện, chạy thực nghiệm so sánh, bóc tách module (Ablation Study) và phân tích lỗi.</li></ul></li><li><strong>Giai đoạn 5: Viết báo cáo &amp; Xuất bản (Drafting Paper &amp; Publication)</strong><ul><li>Soạn thảo theo cấu trúc IMRaD, rà soát trích dẫn và nộp bài.</li></ul></li></ol><hr><h2 id="quy-trinh-5-buoc-literature-review-bang-ai-1" tabindex="-1">QUY TRÌNH 5 BƯỚC LITERATURE REVIEW BẰNG AI <a class="header-anchor" href="#quy-trinh-5-buoc-literature-review-bang-ai-1" aria-label="Permalink to &quot;QUY TRÌNH 5 BƯỚC LITERATURE REVIEW BẰNG AI&quot;">​</a></h2><p>Đây là quy trình ứng dụng AI để nhanh chóng nắm bắt bức tranh toàn cảnh và tìm khoảng trống nghiên cứu (Research Gaps) phục vụ cho <strong>Giai đoạn 1</strong>.</p><h3 id="buoc-1-quet-ban-đo-tri-thuc-gemini-deep-research" tabindex="-1">Bước 1: Quét bản đồ tri thức (Gemini Deep Research) <a class="header-anchor" href="#buoc-1-quet-ban-đo-tri-thuc-gemini-deep-research" aria-label="Permalink to &quot;Bước 1: Quét bản đồ tri thức (Gemini Deep Research)&quot;">​</a></h3><p>Sử dụng Gemini để quét nhanh SOTA (State of the Art), các bộ dữ liệu chuẩn, các thước đo và 10–15 từ khóa vàng trong 2–5 phút.</p><p><strong>Prompt #1.1: Quét Overview &amp; Lập Bản Đồ Tri Thức Toàn Diện</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tôi là nhà nghiên cứu đang làm project về [mô tả chi tiết đề tài/dữ liệu của bạn]. Hãy cung cấp overview toàn diện bao gồm:</span></span>
<span class="line"><span>1. HƯỚNG TIẾP CẬN (Category): Các hướng nghiên cứu chính trong lĩnh vực này là gì? Mô tả ngắn từng hướng.</span></span>
<span class="line"><span>2. STATE OF THE ART: Các phương pháp tốt nhất hiện tại (2022–2025) là gì? Được test trên benchmark nào? Kết quả cụ thể là bao nhiêu?</span></span>
<span class="line"><span>3. DATASET: Các benchmark dataset phổ biến nhất? (tên, kích thước, số class, modality, free/paid)</span></span>
<span class="line"><span>4. METRICS: Các metric chuẩn dùng để đánh giá trong lĩnh vực này?</span></span>
<span class="line"><span>5. RESEARCH GAPS: Các limitation và vấn đề chưa được giải quyết được nhắc đến nhiều nhất?</span></span>
<span class="line"><span>6. VENUES: Conference và journal uy tín nhất trong lĩnh vực này?</span></span>
<span class="line"><span>7. TỪ KHÓA TÌM KIẾM: 10–15 từ khóa tiếng Anh để search Google Scholar, sắp xếp từ rộng đến hẹp.</span></span></code></pre></div><p><strong>Prompt #1.2: Đào Sâu Từng Hướng Tiếp Cận Cụ Thể</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dựa trên overview ở trên, tôi muốn hiểu sâu hơn về hướng [Tên hướng tiếp cận cụ thể]. Hãy cung cấp:</span></span>
<span class="line"><span>1. Cách tiếp cận này hoạt động như thế nào? Giải thích cho sinh viên chưa biết gì về nó.</span></span>
<span class="line"><span>2. Các paper quan trọng nhất theo hướng này: Tên paper, tác giả, năm, venue. Đóng góp chính là gì? Kết quả tốt nhất trên benchmark nào?</span></span>
<span class="line"><span>3. Các paper trong hướng này tiến hóa như thế nào? Paper sau giải quyết vấn đề gì của paper trước?</span></span>
<span class="line"><span>4. Hạn chế lớn nhất của toàn bộ hướng này?</span></span>
<span class="line"><span>5. Tôi nên đọc paper nào trước? Sắp xếp theo độ ưu tiên, không phải theo năm.</span></span></code></pre></div><hr><h3 id="buoc-2-thu-thap-bai-bao-cot-loi-google-scholar" tabindex="-1">Bước 2: Thu thập bài báo cốt lõi (Google Scholar) <a class="header-anchor" href="#buoc-2-thu-thap-bai-bao-cot-loi-google-scholar" aria-label="Permalink to &quot;Bước 2: Thu thập bài báo cốt lõi (Google Scholar)&quot;">​</a></h3><p>Lấy tên paper hoặc từ khóa từ Bước 1 để tìm kiếm trên Google Scholar.</p><ul><li><strong>Nguyên tắc lọc:</strong><ul><li>Bài Foundational (&gt;100 citations): Đọc bắt buộc.</li><li>Bài SOTA gần đây (2022-2025, &gt;20 citations): Đọc kỹ.</li><li>Bài &lt;10 citations và &gt;2 năm tuổi: Cân nhắc bỏ qua.</li></ul></li><li><strong>Tải PDF:</strong> Sử dụng nút &quot;All N versions&quot; trên Scholar, cài đặt extension Unpaywall, hoặc tìm trên semanticscholar.org.</li><li><strong>Cách đặt tên file chuẩn:</strong> <code>[ID]_[AuthorYear].pdf</code> (Ví dụ: <code>P001_Vaswani2017.pdf</code>).</li></ul><hr><h3 id="buoc-3-kiem-chung-hoc-thuat-leapspace" tabindex="-1">Bước 3: Kiểm chứng học thuật (LeapSpace) <a class="header-anchor" href="#buoc-3-kiem-chung-hoc-thuat-leapspace" aria-label="Permalink to &quot;Bước 3: Kiểm chứng học thuật (LeapSpace)&quot;">​</a></h3><p>Sử dụng LeapSpace như một &quot;Kính hiển vi học thuật&quot; để khoanh vùng tìm kiếm trong các nguồn Peer-Reviewed (đã qua bình duyệt) nhằm tránh rủi ro AI hallucination (bịa nguồn).</p><p><strong>Prompt #2.1: Tạo Bảng So Sánh Bài Báo Trong Ngách</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dựa trên các bài báo đã tìm được, hãy tổng hợp thông tin và tạo một bảng so sánh chi tiết. Yêu cầu các cột sau: Tác giả (Năm), Phương pháp chính, Tập dữ liệu (Dataset), Kết quả nổi bật, và Hạn chế của nghiên cứu.</span></span></code></pre></div><p><strong>Prompt #2.2: Deep Research Chuyên Sâu Tạp Chí</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tiến hành Deep Research cho chủ đề: [Điền ngách nghiên cứu cụ thể]. Hãy lập một báo cáo phân tích toàn diện bao gồm: Cơ chế hoạt động, Các kết quả tốt nhất hiện nay (SOTA), Hạn chế của các phương pháp hiện tại, và Đề xuất hướng nghiên cứu tương lai.</span></span></code></pre></div><p><strong>Prompt #2.3: Writing Coach – Phản Biện &amp; Trích Dẫn Cho Văn Nháp</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hãy đóng vai một chuyên gia phản biện học thuật khó tính. Đọc đoạn văn nháp sau của tôi và thực hiện các việc sau:</span></span>
<span class="line"><span>1. Đánh giá xem các luận điểm đã được hỗ trợ chặt chẽ bởi tài liệu chưa.</span></span>
<span class="line"><span>2. Tìm và gắn các trích dẫn (references) phù hợp cho những câu đang thiếu minh chứng.</span></span>
<span class="line"><span>3. Chỉ ra những câu có tính khẳng định quá mức (overstated) và gợi ý cách viết lại cho chuẩn mực học thuật.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Đoạn nháp của tôi: [Dán đoạn văn nháp vào đây]</span></span></code></pre></div><hr><h3 id="buoc-4-đoc-hieu-sau-chot-khoang-trong-notebooklm" tabindex="-1">Bước 4: Đọc hiểu sâu &amp; Chốt khoảng trống (NotebookLM) <a class="header-anchor" href="#buoc-4-đoc-hieu-sau-chot-khoang-trong-notebooklm" aria-label="Permalink to &quot;Bước 4: Đọc hiểu sâu &amp; Chốt khoảng trống (NotebookLM)&quot;">​</a></h3><p>Upload toàn bộ các file PDF đã tải (tối đa 50 sources/notebook) vào Google NotebookLM để phân tích chuyên sâu. Trước khi dùng AI, áp dụng kỹ thuật <strong>Đọc 3-pass</strong> để quét tài liệu: Pass 1 (5 phút Skim), Pass 2 (20 phút Core), Pass 3 (60 phút Deep Method).</p><p><strong>Prompt #3.1: Quét Tổng Quan Tất Cả Paper Đã Upload</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tóm tắt tất cả paper đã upload theo format, mỗi paper 1 dòng, không bỏ sót paper nào:</span></span>
<span class="line"><span>Tên paper | Năm | Method chính | Dataset | Metric | Kết quả tốt nhất | Limitation chính</span></span>
<span class="line"><span>(Trả về định dạng bảng).</span></span></code></pre></div><p><strong>Prompt #3.2: Tạo Bảng So Sánh Kỹ Thuật Chi Tiết</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tạo bảng so sánh tất cả phương pháp trong các paper đã upload với các cột:</span></span>
<span class="line"><span>Method | Backbone | Input Modality | Dataset | Metric | Kết quả | Năm | Tên paper nguồn</span></span>
<span class="line"><span>Yêu cầu:</span></span>
<span class="line"><span>- Sắp xếp theo năm tăng dần.</span></span>
<span class="line"><span>- Mỗi dòng ghi rõ tên paper nguồn.</span></span>
<span class="line"><span>- Nếu 1 paper báo cáo nhiều kết quả trên nhiều dataset, mỗi dòng ghi 1 dataset.</span></span>
<span class="line"><span>- Ghi &quot;-&quot; nếu thông tin không có trong paper.</span></span></code></pre></div><p><strong>Prompt #3.3: Khai Thác Khoảng Trống Nghiên Cứu (Research Gap Focus)</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dựa trên phần Limitation và Future Work của tất cả paper đã upload:</span></span>
<span class="line"><span>1. Liệt kê tất cả vấn đề chưa được giải quyết. Không nói chung chung, phải cụ thể.</span></span>
<span class="line"><span>2. Nhóm các vấn đề theo loại:</span></span>
<span class="line"><span>   - Chi phí tính toán</span></span>
<span class="line"><span>   - Thiếu dữ liệu / dataset</span></span>
<span class="line"><span>   - Khả năng generalize</span></span>
<span class="line"><span>   - Real-time performance</span></span>
<span class="line"><span>   - Đa phương thức / multi-modal</span></span>
<span class="line"><span>   - Khác (nêu rõ)</span></span>
<span class="line"><span>3. Với mỗi gap, chỉ rõ: Paper nào đề cập đến gap này? Gap này được bao nhiêu paper thừa nhận?</span></span>
<span class="line"><span>4. Gap nào xuất hiện nhiều nhất? Gap nào ít được giải quyết nhất gần đây (2022-2025)?</span></span></code></pre></div><hr><h3 id="buoc-5-cau-truc-co-so-du-lieu-csv-google-sheets" tabindex="-1">Bước 5: Cấu trúc cơ sở dữ liệu (CSV / Google Sheets) <a class="header-anchor" href="#buoc-5-cau-truc-co-so-du-lieu-csv-google-sheets" aria-label="Permalink to &quot;Bước 5: Cấu trúc cơ sở dữ liệu (CSV / Google Sheets)&quot;">​</a></h3><p>Chuyển đổi các kết quả tóm tắt thành dạng bảng chuẩn để paste vào Google Sheets nhằm quản lý lâu dài.</p><p><strong>Prompt #4: Định Dạng Bảng Chuẩn (Chạy trên Gemini)</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dưới đây là tóm tắt các paper từ NotebookLM:</span></span>
<span class="line"><span>[Dán output từ Prompt #3.1 vào đây]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hãy tạo bảng Markdown với các cột sau, mỗi paper 1 dòng, không bỏ sót paper nào:</span></span>
<span class="line"><span>| ID | Title | Authors | Year | Venue | Venue_Rank | DOI_URL | Method | Dataset | Best_Result | Key_Contribution | Limitation | Read_Status | Citation_Key | Notes |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Yêu cầu chi tiết cho từng cột:</span></span>
<span class="line"><span>- ID: Đánh số thứ tự P001, P002, P003...</span></span>
<span class="line"><span>- Authors: &quot;Last et al.&quot; nếu &gt;2 tác giả, &quot;Last &amp; Last&quot; nếu đúng 2 tác giả.</span></span>
<span class="line"><span>- Venue: Tên conference hoặc journal đầy đủ.</span></span>
<span class="line"><span>- Venue_Rank: Xếp hạng (Journal: Q1/Q2/Q3/Q4; Conference: A*/A/B/C). Ghi &quot;-&quot; nếu không rõ.</span></span>
<span class="line"><span>- DOI_URL: Link arXiv hoặc DOI.</span></span>
<span class="line"><span>- Method: Tên phương pháp chính, ngắn gọn.</span></span>
<span class="line"><span>- Dataset: Tên dataset, ngăn cách &quot;;&quot; nếu nhiều dataset.</span></span>
<span class="line"><span>- Best_Result: Gộp metric và số liệu (VD: &quot;Top-1 Acc: 89.3%&quot;).</span></span>
<span class="line"><span>- Key_Contribution: Tối đa 15 từ tiếng Anh.</span></span>
<span class="line"><span>- Limitation: Tối đa 10 từ tiếng Anh.</span></span>
<span class="line"><span>- Read_Status: Điền &quot;TODO&quot; cho tất cả.</span></span>
<span class="line"><span>- Citation_Key: [LastName][Year][FirstWordTitle] (VD: vaswani2017attention).</span></span>
<span class="line"><span>- Notes: Điền &quot;-&quot; cho tất cả.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chỉ trả về bảng Markdown, không giải thích thêm.</span></span></code></pre></div><p>Sau khi có bảng Markdown, dán vào Google Sheets và áp dụng <strong>Conditional Formatting</strong> (định dạng có điều kiện) cho cột <code>Read_Status</code> (TODO/Skimmed/Done) và <code>Relevance</code> (High/Medium/Low) để dễ dàng tra cứu, lọc (filter) thay vì phải nhớ thủ công.</p>`,42)])])}const d=a(i,[["render",p]]);export{g as __pageData,d as default};
